import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {usePropertySource} from '../hooks/use-property-source'

import {StafftoolsCustomProperties} from '@github-ui/stafftools-custom-properties-core'
import type {CustomPropertyDefinitionPayload} from '@github-ui/stafftools-custom-properties-core/types'

export function CustomPropertyDefinitionShowPage() {
  const {definition} = useRoutePayload<CustomPropertyDefinitionPayload>()
  const {name, description, required, defaultValue, valueType, allowedValues} = definition

  const {getDefinitionListPath, source} = usePropertySource()

  return (
    <StafftoolsCustomProperties>
      <StafftoolsCustomProperties.NavigationHeader
        target="Repository"
        propertyName={name}
        listPath={getDefinitionListPath(source)}
      />
      <StafftoolsCustomProperties.DefinitionTextField label="Description" value={description} />
      <StafftoolsCustomProperties.DefinitionTextField label="Value type" value={valueType} />
      <StafftoolsCustomProperties.DefinitionBooleanField label="Required" value={required} />
      <StafftoolsCustomProperties.DefinitionTextField label="Default value" value={defaultValue} />
      <StafftoolsCustomProperties.DefinitionListField label="Allowed values" values={allowedValues} />
    </StafftoolsCustomProperties>
  )
}

try{ CustomPropertyDefinitionShowPage.displayName ||= 'CustomPropertyDefinitionShowPage' } catch {}